<?php
require_once __DIR__ . '/../database/app/layout.php';$u=require_role(['restaurant','event_organizer','ngo','admin']);$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();try{$deliveryId=(int)($_POST['delivery_id']??0);$rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');if($rating<1||$rating>5)throw new RuntimeException('Choose a rating from 1 to 5.');if(strlen($comment)>1000)throw new RuntimeException('Comment must be under 1000 characters.');
 $q=$pdo->prepare("SELECT d.id,d.status,dr.requested_by,sf.restaurant_id FROM deliveries d JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id WHERE d.id=? AND d.status IN ('delivered','completed')");$q->execute([$deliveryId]);$tx=$q->fetch();if(!$tx)throw new RuntimeException('Feedback is only available for delivered or completed transactions.');$donor=(int)$tx['restaurant_id'];$ngo=(int)$tx['requested_by'];if($u['role']!=='admin'&&!in_array((int)$u['id'],[$donor,$ngo],true))throw new RuntimeException('You are not a participant in this transaction.');if($u['role']==='admin')throw new RuntimeException('Admin accounts cannot leave donor/NGO feedback.');$reviewee=(int)$u['id']===$donor?$ngo:$donor;if($reviewee===(int)$u['id'])throw new RuntimeException('Reviewer and reviewee must be different accounts.');$pdo->prepare("INSERT INTO transaction_feedback(delivery_id,reviewer_id,reviewee_id,rating,comment,moderation_status) VALUES(?,?,?,?,?,'published')")->execute([$deliveryId,$u['id'],$reviewee,$rating,$comment]);audit((int)$u['id'],'feedback_submitted','deliveries',$deliveryId,'rating='.$rating);flash('Feedback saved. Thank you for helping build trust.');redirect('feedback.php');}catch(Throwable $e){$errors[]=$e instanceof RuntimeException?$e->getMessage():'Feedback could not be saved. You may have already reviewed this delivery.';}}
$eligible=[];if($u['role']!=='admin'){$q=$pdo->prepare("SELECT d.id AS delivery_id,d.status,dr.id AS request_id,sf.food_name,donor.id AS donor_id,donor.name AS donor_name,ngo.id AS ngo_id,ngo.name AS ngo_name,dr.updated_at FROM deliveries d JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id JOIN users donor ON donor.id=sf.restaurant_id JOIN users ngo ON ngo.id=dr.requested_by WHERE d.status IN ('delivered','completed') AND (donor.id=? OR ngo.id=?) AND NOT EXISTS(SELECT 1 FROM transaction_feedback f WHERE f.delivery_id=d.id AND f.reviewer_id=?) ORDER BY d.updated_at DESC");$q->execute([$u['id'],$u['id'],$u['id']]);$eligible=$q->fetchAll();}
$ratings=$pdo->query("SELECT u.name,u.role,COUNT(f.id) AS review_count,ROUND(AVG(f.rating),2) AS average_rating FROM users u JOIN transaction_feedback f ON f.reviewee_id=u.id WHERE f.moderation_status='published' GROUP BY u.id,u.name,u.role HAVING COUNT(f.id)>0 ORDER BY average_rating DESC,review_count DESC LIMIT 100")->fetchAll();
$q=$pdo->prepare("SELECT f.*,d.id AS delivery_ref,u.name AS reviewee_name,sf.food_name FROM transaction_feedback f JOIN deliveries d ON d.id=f.delivery_id JOIN users u ON u.id=f.reviewee_id JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id WHERE f.reviewer_id=? ORDER BY f.created_at DESC LIMIT 100");$q->execute([$u['id']]);$mine=$q->fetchAll();
page_header('Donor and NGO feedback');?>
<div class="page-intro"><div class="eyebrow">TRUST & ACCOUNTABILITY</div><h1>Donor–NGO <em>feedback.</em></h1><p>Only participants in a delivered or completed transaction may review each other. Each account can submit one review per delivery.</p></div><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?>
<?php if($u['role']!=='admin'):?><div class="form-panel"><h2>Review a completed transaction</h2><?php if(!$eligible):?><p class="muted">No eligible unreviewed transactions found.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="full">Delivery / transaction<select name="delivery_id" required><option value="">Choose transaction</option><?php foreach($eligible as $r):$other=(int)$u['id']===(int)$r['donor_id']?$r['ngo_name']:$r['donor_name'];?><option value="<?=(int)$r['delivery_id']?>">Delivery #<?=(int)$r['delivery_id']?> · <?=e($r['food_name'])?> · review <?=e($other)?></option><?php endforeach;?></select></label><label>Rating<select name="rating" required><option value="">Select stars</option><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Okay</option><option value="2">2 — Poor</option><option value="1">1 — Very poor</option></select></label><label class="full">Comment (optional)<textarea name="comment" maxlength="1000" rows="3" placeholder="Describe the transaction experience respectfully"></textarea></label><div class="full"><button class="btn" type="submit">Submit feedback</button></div></form><?php endif;?></div><?php endif;?>
<div class="section-heading"><div><div class="eyebrow">COMMUNITY RATINGS</div><h2>Published ratings</h2></div></div><div class="table-wrap"><table><thead><tr><th>Organisation / account</th><th>Role</th><th>Average rating</th><th>Reviews</th></tr></thead><tbody><?php foreach($ratings as $r):?><tr><td><?=e($r['name'])?></td><td><?=e(ucwords(str_replace('_',' ',$r['role'])))?></td><td>★ <?=number_format((float)$r['average_rating'],2)?> / 5</td><td><?=(int)$r['review_count']?></td></tr><?php endforeach;?><?php if(!$ratings):?><tr><td colspan="4" class="table-empty">No published feedback yet.</td></tr><?php endif;?></tbody></table></div>
<div class="section-heading"><div><div class="eyebrow">YOUR REVIEWS</div><h2>Feedback submitted</h2></div></div><div class="table-wrap"><table><thead><tr><th>Delivery</th><th>Food</th><th>Reviewed account</th><th>Rating</th><th>Comment</th><th>Date</th></tr></thead><tbody><?php foreach($mine as $r):?><tr><td>#<?=(int)$r['delivery_ref']?></td><td><?=e($r['food_name'])?></td><td><?=e($r['reviewee_name'])?></td><td><?=str_repeat('★',(int)$r['rating'])?></td><td><?=e($r['comment']??'')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$mine):?><tr><td colspan="6" class="table-empty">No feedback submitted from this account.</td></tr><?php endif;?></tbody></table></div><?php page_footer();?>
